"use strict";

function chapter(factionId, number, spec, climax = false) {
  const entry = {
    id: `${factionId}-${spec.slug}`,
    playableName: spec.hero,
    opponentName: spec.foe,
    title: spec.title,
    story: spec.story,
    dialogue: [
      `Narrator: ${spec.before}`,
      `${spec.hero}: ${spec.heroLine}`,
      `${spec.foe}: ${spec.foeLine}`,
      `${spec.ally}: ${spec.allyLine}`,
      `${spec.hero}: ${spec.answer}`
    ],
    endDialogue: [
      `Narrator: ${spec.after}`,
      `${spec.foe}: ${spec.foeAfter}`,
      `${spec.ally}: ${spec.allyAfter}`,
      `${spec.hero}: ${spec.finalLine}`,
      `Narrator: Chapter ${number} closes, but its choice changes every battle that follows.`
    ]
  };
  if (climax) {
    entry.cinematic = {
      kicker: spec.kicker,
      title: spec.title,
      subtitle: spec.subtitle,
      image: spec.image
    };
  }
  return entry;
}

function makeCampaign(factionId, specs) {
  return specs.map((spec, index) => chapter(factionId, index + 1, spec, index === specs.length - 1));
}

const CAMPAIGNS = {
  mekan: makeCampaign("mekan", [
    { slug: "flower-ringed-lake", title: "The Flower-Ringed Lake", hero: "Acama", foe: "The Bone Road Marauders", ally: "Hui", story: "The wandering Mekan find the lake that will become San Mikal and must defend the living long enough to hear their ancestors clearly.", before: "At a lake ringed with impossible flowers, Acama hears music from relatives dead for generations while marauders close on the exhausted caravan.", heroLine: "If our dead found this place, the living will not abandon it.", foeLine: "Bones do not own land.", allyLine: "No, but memory can teach hands how to defend it.", answer: "Raise the lanterns. Let every generation see where we stand.", after: "The caravan holds the shore and lays San Mikal's first stones around a shared burial garden.", foeAfter: "Keep your haunted lake.", allyAfter: "They call it haunted because no one remembers them.", finalLine: "Then our city will remember enough for everyone." },
    { slug: "first-guest", title: "The First Guest", hero: "Acama", foe: "The Silent Ferryman", ally: "Hui", story: "The first successful Recursion returns a beloved musician, forcing the Mekan to decide whether a spirit is a citizen, a miracle, or a prisoner.", before: "A funeral song answers itself from inside the ceremonial chamber, and the first Guest asks why the doors are locked.", heroLine: "We invited you home. We did not summon a servant.", foeLine: "Every returned soul owes the living a price.", allyLine: "A guest who cannot leave is only a captive with flowers.", answer: "Open the chamber and let the dead choose the length of the dance.", after: "The musician performs until dawn, embraces her descendants, and departs by choice.", foeAfter: "You surrendered eternity.", allyAfter: "We protected consent.", finalLine: "Recursion will be a reunion, never a chain." },
    { slug: "lantern-procession", title: "The Lantern Procession", hero: "Hui", foe: "The Ash-Mask Gang", ally: "Temo", story: "San Mikal's first public festival is attacked by thieves who believe the dead carry buried treasure.", before: "Thousands of lanterns guide Guests through streets still smelling of new timber when masked raiders enter the procession.", heroLine: "No one draws steel in a welcome line.", foeLine: "Your ancestors brought their jewelry back for us.", allyLine: "They also brought their warriors.", answer: "Then let the procession keep its rhythm while we remove the interruption.", after: "Living dancers and Revenant guardians finish the route together without extinguishing a single lantern.", foeAfter: "This city celebrates like an army.", allyAfter: "An army marches for conquest. We march people home.", finalLine: "Next year even our enemies may attend unmasked." },
    { slug: "spectral-symphony", title: "The Spectral Symphony", hero: "Hui", foe: "Maestro Veyra", ally: "Allegro", story: "A rival conductor tries to bind departed musicians into an immortal orchestra, testing the sacred limits of Recursion.", before: "Maestro Veyra locks the concert hall and orders the dead to play the same perfect movement forever.", heroLine: "Music remembered is alive. Music imprisoned is noise.", foeLine: "Perfection requires performers who cannot refuse.", allyLine: "Then perfection has forgotten why anyone listens.", answer: "Break the seals. The final note belongs to the musicians.", after: "The bound orchestra changes Veyra's score, performs one joyful improvisation, and walks into the dawn.", foeAfter: "They ruined my masterpiece.", allyAfter: "They made it theirs.", finalLine: "San Mikal will applaud freedom, even when it misses a note." },
    { slug: "jade-ball", title: "The Jade Ball Challenge", hero: "Ahu", foe: "Champion Xoco", ally: "Monti", story: "A ceremonial game becomes a political contest when an undefeated champion demands control of the festival grounds.", before: "Champion Xoco wagers that one victory should decide who hosts the dead and commands the living crowds.", heroLine: "A festival is not a throne to win.", foeLine: "Everything worth holding has a champion.", allyLine: "Then we will show you a city is held by more than one pair of hands.", answer: "Play the match. The crowd will decide what the score means.", after: "Ahu wins, then invites Xoco's team to lead next year's opening procession.", foeAfter: "You deny yourself the prize.", allyAfter: "We deny the prize the power to divide us.", finalLine: "Competition ends. Community must continue." },
    { slug: "the-empty-chair", title: "The Empty Chair", hero: "Temo", foe: "The Grief Eater", ally: "Allegro", story: "A spirit feeds on mourners by impersonating the people they lost, turning remembrance into dependence.", before: "Every home in one district sets an extra chair, but the same hungry voice answers from all of them.", heroLine: "You wear beloved faces without carrying their memories.", foeLine: "Grief does not care about the difference.", allyLine: "That is why we must.", answer: "Call each ancestor by the story only their family knows.", after: "The false voices fade when families tell imperfect, specific memories no imitation can steal.", foeAfter: "They will miss the comfort I gave.", allyAfter: "Comfort that consumes them is another hunger.", finalLine: "We honor absence too. The empty chair may remain empty." },
    { slug: "war-of-returning", title: "The War of Returning", hero: "Allegro", foe: "General Calavera", ally: "Acama", story: "A Mekan general raises an army that cannot stay dead and claims eternal security justifies permanent conscription.", before: "General Calavera marches generations of unwilling soldiers toward San Mikal under banners sewn from funeral cloth.", heroLine: "You turned remembrance into recruitment.", foeLine: "I ended the fear of losing warriors.", allyLine: "By teaching every family to fear burial.", answer: "We will free the Guests before we defeat their general.", after: "The returned army lays down its weapons as Allegro breaks the names binding it to Calavera.", foeAfter: "Without my command they are nothing.", allyAfter: "Without your command they are themselves.", finalLine: "No Mekan victory will be built from captive ancestors." },
    { slug: "festival-without-end", title: "The Festival Without End", hero: "Monti", foe: "The Gilded Host", ally: "Temo", story: "A wealthy Host refuses to let a sacred celebration end, exhausting the city and trapping its Guests in endless spectacle.", before: "On the thirteenth dawn of a three-day festival, the drums still sound and the dead can no longer find the road away.", heroLine: "A celebration needs an ending so another can begin.", foeLine: "Joy that stops was never joy.", allyLine: "The dancers are collapsing while you count applause.", answer: "Silence the drums. We will honor the final bow.", after: "Monti extinguishes the central lantern and the Guests depart through a city finally quiet enough to grieve.", foeAfter: "You killed the wonder.", allyAfter: "We gave wonder back its meaning.", finalLine: "Tomorrow we rest. Next year we dance again." },
    { slug: "the-stolen-names", title: "The Stolen Names", hero: "Temo", foe: "Archivist Silex", ally: "Hui", story: "An archivist erases unpopular dead from San Mikal's rolls, threatening the memory on which Recursion depends.", before: "Families arrive for the Procession and discover entire bloodlines removed from the ceremonial archive.", heroLine: "A name omitted twice becomes a second death.", foeLine: "History cannot carry everyone.", allyLine: "Then history needs stronger shoulders.", answer: "Open the sealed stacks. We restore every name tonight.", after: "The erased Guests return as citizens recite recovered names through every street in San Mikal.", foeAfter: "You restored criminals beside heroes.", allyAfter: "Memory is testimony, not praise.", finalLine: "We remember the whole life, then judge it honestly." },
    { slug: "siege-of-san-mikal", title: "The Siege of San Mikal", hero: "Allegro", foe: "The Pale Conquistador", ally: "Ahu", story: "An invader seeks the Recursion chambers to build an empire whose soldiers return after every defeat.", before: "The Pale Conquistador surrounds San Mikal and offers peace in exchange for the city's dead.", heroLine: "Our Guests are people, not weapons in storage.", foeLine: "Every empire is built from resources others sentimentalize.", allyLine: "Then your empire has never met a resource that can refuse.", answer: "Invite every defender, living and departed. No one is commanded to stay.", after: "Voluntary Guests hold the gates long enough for the invader's conscript army to see what choice looks like.", foeAfter: "Your mercy made them dangerous.", allyAfter: "Their freedom did.", finalLine: "San Mikal survives because anyone may leave it." },
    { slug: "one-more-song", title: "One More Song", hero: "Allegro", foe: "The Quiet Plague", ally: "Monti", story: "A plague attacks memory rather than flesh, silencing names and threatening every bridge between the Mekan generations.", before: "Songs lose verses, portraits lose faces, and Guests flicker as the Quiet Plague reaches the burial grounds.", heroLine: "If memory fails, we will teach it to begin again.", foeLine: "All songs end in silence.", allyLine: "Silence is where musicians breathe.", answer: "Share every story. No archive stands alone tonight.", after: "The city distributes its memories among thousands of voices, leaving the plague no single archive to destroy.", foeAfter: "You made your history inconsistent.", allyAfter: "We made it alive.", finalLine: "A remembered life may change in the telling and still remain loved." },
    { slug: "grand-reunion", title: "The Grand Reunion", hero: "Allegro", foe: "The Keeper Beyond", ally: "Acama", story: "When the boundary between worlds begins closing, Allegro leads one final celebration to prove the Mekan can cherish the dead without refusing the future.", before: "The Keeper Beyond announces that the road of Recursion must close before both worlds collapse into one endless past.", heroLine: "Give us one night to say goodbye without pretending it is forever.", foeLine: "Mortals always ask eternity for one more hour.", allyLine: "Because one honest hour can finish what centuries avoided.", answer: "Open the gates for the final invitation. No chains, no commands, no unfinished songs.", after: "At sunrise the Guests depart willingly, and San Mikal discovers remembrance can endure without possession.", foeAfter: "The road is closed.", allyAfter: "The stories remain open.", finalLine: "One more song was enough. Now the living write the next verse.", kicker: "The final invitation", subtitle: "The dead depart. The celebration continues in living hands.", image: "/assets/gauntlet/mekan-emblem.svg" }
  ]),
  jali: makeCampaign("jali", [
    { slug: "line-after-loss", title: "The Line After Loss", hero: "Watane", foe: "Lord Haruto", ally: "Basho", story: "Watane discovers the first Revenant when a defeated warrior rises to fill the breach she left behind.", before: "A small Jali formation breaks beneath Haruto's cavalry, but the fallen refuse to abandon the line.", heroLine: "Defeat opened a place. Memory will hold it.", foeLine: "Ghosts cannot restore a broken army.", allyLine: "They do not restore it. They teach the survivors where it broke.", answer: "Reform the line around them.", after: "The Jali counterattack turns its first loss into the battle's decisive formation.", foeAfter: "You fight better after losing.", allyAfter: "Only if we listen to what the loss says.", finalLine: "The bested rise, and the living answer." },
    { slug: "three-hidden-banners", title: "Three Hidden Banners", hero: "Basho", foe: "The Mirror Clan", ally: "Watane", story: "Basho develops the revealed formation while a rival clan reads every conventional Jali maneuver.", before: "The Mirror Clan predicts every visible formation, forcing Basho to hide one card in each lane.", heroLine: "A formation can be honest without being obvious.", foeLine: "Reveal your line and we will copy it.", allyLine: "Then they will copy the shape after its purpose has changed.", answer: "Three banners down. Reveal only at my signal.", after: "Basho reveals all three lanes at once and the Mirror Clan answers a formation that no longer exists.", foeAfter: "You made secrecy into doctrine.", allyAfter: "Only until the decisive moment.", finalLine: "The reveal is part of the strike." },
    { slug: "floating-city", title: "Katana Takes Flight", hero: "Watane", foe: "Admiral Sevrin", ally: "Basho", story: "The Jali defend the engines that lift Katana above an invading fleet and make the floating city their permanent home.", before: "Katana's unfinished lifting engines ignite while Sevrin's fleet fires on the anchors below.", heroLine: "Cut the anchors only after the last citizen boards.", foeLine: "Your city will fall before it learns to fly.", allyLine: "Then we will build the formation in the sky.", answer: "Hold all three engine lanes.", after: "Katana rises through smoke, carrying the Jali beyond the reach of the fleet below.", foeAfter: "Cities belong to earth.", allyAfter: "So did every person before their first step.", finalLine: "Let the horizon become our wall." },
    { slug: "bested-prince", title: "The Bested Prince", hero: "Watane", foe: "Prince Daigo", ally: "The First Revenant", story: "A defeated prince demands resurrection as a right and tries to command the Revenants as royal property.", before: "Prince Daigo enters Katana's memorial hall and orders every Revenant to kneel.", heroLine: "Death did not enlarge your crown.", foeLine: "My bloodline commands the loyalty of its dead.", allyLine: "We remember serving. We also remember why we stopped.", answer: "Let the Revenants speak before the prince does again.", after: "Daigo's own ancestors strip his claim of its sacred language and return authority to the formation.", foeAfter: "The dead betrayed their house.", allyAfter: "We corrected its living heir.", finalLine: "Memory owes no obedience to rank." },
    { slug: "storm-formation", title: "Formation in the Storm", hero: "Basho", foe: "The Thunder Ronin", ally: "Watane", story: "A supernatural storm scatters Katana's lanes and forces Basho to build a formation without stable ground.", before: "Lightning shears bridges from Katana while the Thunder Ronin attacks through the gaps.", heroLine: "A lane is a promise between warriors, not a line painted on stone.", foeLine: "Then make your promises in the wind.", allyLine: "We already made them in defeat.", answer: "Anchor to one another. Reveal on the thunder.", after: "The three-lane formation survives by moving as one body across the fractured city.", foeAfter: "No wall held you.", allyAfter: "We did not need one.", finalLine: "Discipline is portable." },
    { slug: "revenant-famine", title: "The Revenant Famine", hero: "Watane", foe: "The White Abbot", ally: "Basho", story: "A long peace produces no Revenants, and a priest argues the Jali must manufacture losses to preserve their strength.", before: "The White Abbot proposes ritual defeats so Katana will never lack Revenants.", heroLine: "We do not injure our people to feed a strategy.", foeLine: "Peace has made your greatest weapon scarce.", allyLine: "Then peace is the resource we protect.", answer: "Fight without Revenants and prove doctrine serves life.", after: "Watane wins with an ordinary formation and ends the practice of ceremonial besting.", foeAfter: "You chose weakness.", allyAfter: "We chose not to worship pain.", finalLine: "A Revenant is a response to loss, never a reason for it." },
    { slug: "paper-moon-coup", title: "The Paper Moon Coup", hero: "Basho", foe: "Minister Kuro", ally: "Watane", story: "A minister uses false Revenants and forged memories to seize control of Katana's council.", before: "Minister Kuro fills the council chamber with masked spirits reciting convenient histories.", heroLine: "A formation is revealed so others can inspect it.", foeLine: "Truth is simply the memory that holds the room.", allyLine: "Then let every witness enter the room.", answer: "Remove the masks and name each source.", after: "The false Revenants collapse when their stories cannot survive public questioning.", foeAfter: "People preferred my version.", allyAfter: "Preference does not make an ancestor.", finalLine: "Memory earns authority through scrutiny." },
    { slug: "falling-katana", title: "When Katana Fell", hero: "Watane", foe: "The Chain Artificer", ally: "Basho", story: "Saboteurs disable Katana's lift engines, forcing the Jali to defend a falling city lane by lane.", before: "Katana descends toward the mountains while the Chain Artificer locks every repair crew behind summoned soldiers.", heroLine: "Every lost engine creates another place to stand.", foeLine: "Your philosophy will not change gravity.", allyLine: "No. Our formation will change where the city lands.", answer: "Hold the repair lanes until the final ignition.", after: "One engine restarts and Basho turns Katana's fall into a controlled landing on an uninhabited ridge.", foeAfter: "Your floating city is grounded.", allyAfter: "Ground is only today's battlefield.", finalLine: "Katana has risen once. It remembers how." },
    { slug: "warrior-without-memory", title: "The Warrior Without Memory", hero: "Watane", foe: "Nameless Revenant", ally: "Basho", story: "A powerful Revenant returns without identity and challenges the Jali belief that memory gives the dead purpose.", before: "A nameless spirit defeats every guardian while asking who it is supposed to serve.", heroLine: "You may choose before you remember.", foeLine: "Choice without a past is an empty weapon.", allyLine: "A formation gives direction, not ownership.", answer: "Stand with us for this battle, then leave if the answer feels false.", after: "The Nameless Revenant protects Katana and departs to search for its own history.", foeAfter: "I still do not know my name.", allyAfter: "Now you know one choice you made freely.", finalLine: "Identity can begin after resurrection." },
    { slug: "seven-clan-war", title: "The Seven-Clan War", hero: "Basho", foe: "General Akari", ally: "Watane", story: "Seven Jali clans turn their Revenants against one another until Basho reveals that every side remembers the same original betrayal differently.", before: "Katana becomes seven overlapping battlefields, each clan certain its ancestors demand revenge.", heroLine: "If all seven histories are sacred, none grants permission to kill.", foeLine: "My dead remember your treachery.", allyLine: "So do ours, with the names reversed.", answer: "Reveal every formation and compare the missing spaces.", after: "The contradictions expose a forged memorial planted generations earlier to keep the clans divided.", foeAfter: "Without vengeance, what binds us?", allyAfter: "The choice to build something our dead never saw.", finalLine: "Let shared doubt end inherited war." },
    { slug: "last-revenant", title: "The Last Revenant", hero: "Watane", foe: "The Oblivion Bell", ally: "Basho", story: "A weapon erases Revenants permanently, forcing the Jali to defend their living culture without relying on return.", before: "Each toll of the Oblivion Bell removes one spirit from every Jali memory.", heroLine: "We are more than the warriors who return.", foeLine: "Then prove it when none of them can answer.", allyLine: "The formation was learned from them. Learning remains.", answer: "Fight as their students, not their dependents.", after: "The living Jali silence the bell and discover their doctrine survived inside practiced hands.", foeAfter: "Your dead are gone.", allyAfter: "Their commands are gone. Their lessons are ours.", finalLine: "We can honor the bested without asking them to fight forever." },
    { slug: "formation-eternal", title: "The Eternal Formation", hero: "Watane", foe: "The Emperor of Empty Armor", ally: "Basho", story: "An immortal conqueror attacks Katana with soldiers who cannot be bested because nothing living remains inside them.", before: "The Emperor of Empty Armor surrounds Katana with a perfect army that neither fears defeat nor leaves memories behind.", heroLine: "A formation without lives is only geometry.", foeLine: "Geometry does not grieve, hesitate, or rebel.", allyLine: "It also cannot understand why we change.", answer: "Break pattern. Let every lane answer differently.", after: "The Jali abandon the expected formation, turning adaptation and living judgment against the immortal machine.", foeAfter: "You discarded your doctrine.", allyAfter: "We fulfilled it by learning from the last exchange.", finalLine: "The eternal formation is the one that can become new.", kicker: "The line changes", subtitle: "The Jali honor every loss by refusing to repeat it blindly.", image: "/assets/gauntlet/jali-emblem.svg" }
  ]),
  gracus: makeCampaign("gracus", [
    { slug: "cliffs-of-athun", title: "The City of Questions", hero: "Epicura", foe: "Alexiti", ally: "Socratus", story: "On the Gracus homeworld Thalassa, Epicura opposes Alexiti's demand that Athun conquer rebellious city-states before uncertainty becomes civil war.", before: "Sunlight crosses Athun's marble harbors as Alexiti returns to the Hall of Voices with attacked trade routes, missing soldiers, and a demand to march.", heroLine: "If every disagreement becomes rebellion, every neighbor eventually becomes an enemy.", foeLine: "If every enemy becomes a debate, no one will remain to finish the argument.", allyLine: "Before choosing war, ask who profits when both answers require it.", answer: "We investigate the coast and defend its people without conquering them.", after: "Epicura wins authority for a limited mission, but Alexiti leaves certain that hesitation will cost Athun dearly.", foeAfter: "Bring back certainty, or I will bring back order.", allyAfter: "Certainty is usually the first casualty of an honest question.", finalLine: "Then let Athun see us reason under pressure." },
    { slug: "first-minotaur", title: "The First Crack", hero: "Epicura", foe: "Governor Nemeon", ally: "Themin", story: "Epicura and Themin expose provocations that have turned a frightened coastal settlement against Athun.", before: "Governor Nemeon has seized a port and blames Athun for attacks that arrive under contradictory banners.", heroLine: "You cannot protect a city by deciding every unanswered question is treason.", foeLine: "Questions did not bury my scouts.", allyLine: "No, but forged orders sent them to the wrong pass.", answer: "Hold the harbor, compare the orders, and leave Nemeon a road back from fear.", after: "The forged seals match no city-state. Someone has manufactured evidence for every side.", foeAfter: "I defended my people from a lie.", allyAfter: "Now help us find the author.", finalLine: "Athun returns with proof of danger and no convenient enemy." },
    { slug: "towering-follow-up", title: "The Wall of Leo", hero: "Epicura", foe: "Leo", ally: "Themin", story: "The mountain defender Leo seals his passes after receiving false commands from Athun, forcing Epicura to earn a hearing through a controlled war exercise.", before: "Caravans burn below Leo's gates while each surviving messenger carries a different order bearing Athun's seal.", heroLine: "Your wall preserved lives. It is now preserving the lie that isolated you.", foeLine: "Stone does not forge orders or vanish in the night.", allyLine: "Stone also cannot tell which friend is knocking.", answer: "Test our formation. If we break your defense, hear the evidence we carried through it.", after: "Epicura outmaneuvers Leo without breaching the civilian refuge, and the defender joins the investigation.", foeAfter: "I still do not trust Athun.", allyAfter: "Neither do we. We trust what survives examination.", finalLine: "Then stand with us until the source is visible." },
    { slug: "tribute-refused", title: "The Question of Socratus", hero: "Socratus", foe: "The Certainty League", ally: "Epicura", story: "Socratus challenges Athun's Senate, its frightened citizens, and Epicura while tracing the forged orders to a buried sanctuary.", before: "Competing factions fill Athun's plazas, each promising safety if the city stops listening to everyone else.", heroLine: "A leader who cannot answer questions is already ruled by the answer they fear.", foeLine: "Debate is a luxury during invasion.", allyLine: "Then name the invader instead of arresting whoever asks.", answer: "Open the archives, compare every seal, and follow the contradiction beneath the mountains.", after: "The evidence points to an abandoned sanctuary older than Athun, but Alexiti acts before Epicura can enter it.", foeAfter: "While you questioned, the army restored the streets.", allyAfter: "A silent street can hide a marching prison.", finalLine: "We found where the lies began. Now we survive what they enabled." },
    { slug: "arena-of-echoes", title: "Alexiti's Peace", hero: "Epicura", foe: "Alexiti", ally: "Leo", story: "Alexiti occupies Athun without massacre and offers a peaceful authoritarian order that many exhausted citizens welcome.", before: "Military governors replace the Senate, roads reopen, and Athun becomes calm enough to make coercion look like rescue.", heroLine: "You gave the city silence and called the absence of objection consent.", foeLine: "Silence is preferable to screaming.", allyLine: "A wall may protect a voice. It must never become the reason voices disappear.", answer: "We leave Athun alive, gather proof, and return before emergency becomes tradition.", after: "Alexiti lets Epicura depart, confident that philosophy will fail outside the safety his army created.", foeAfter: "When reason fails you, Athun will still be here.", allyAfter: "If no one may disagree with Athun, only the buildings remain.", finalLine: "We will return with an answer stronger than obedience." },
    { slug: "giants-coast", title: "Everything Flows", hero: "Hera", foe: "The Moving Statues", ally: "Epicura", story: "The philosopher Hera reveals that Thalassa's oldest monuments are cracking and that the first Gracus imprisoned something beneath Athun.", before: "Statues change position between observations while carvings of the first awakening shed stone from an erased panel.", heroLine: "We built a civilization from stone and mistook endurance for permanence.", foeLine: "RETURN TO THE FORM THAT MADE YOU.", allyLine: "A beginning is evidence, not ownership.", answer: "Record every change, free the trapped scholars, and open the erased wall.", after: "Behind the panel lies an image of the first Gracus containing a black polyhedral stone.", foeAfter: "ONE STONE. ONE MEMORY. ONE PEACE.", allyAfter: "Peace that erases the speaker is only quiet matter.", finalLine: "Nothing remains fixed, which means neither does our fate." },
    { slug: "broken-horn", title: "The Labyrinth", hero: "Epicura", foe: "Keeper Theros", ally: "Hera", story: "Beneath Athun, mythic creatures guard the Keepers of the First Stone, who admit engineering the crisis so the Gracus would accept one ruler.", before: "Minotaurs, Gorgons, and Gryphons defend corridors older than every Gracus city-state.", heroLine: "You created the fear, then offered submission as its cure.", foeLine: "We reminded a divided people that unity is survival.", allyLine: "A conclusion built from falsified evidence is staging, not unity.", answer: "Free the creatures from the lattice and carry the Keepers' records to Athun.", after: "Theros reveals that Alexiti's centralized government was simply the easiest system to capture.", foeAfter: "The conqueror gathered every institution into one hand for us.", allyAfter: "Then one honest fracture can break your grip.", finalLine: "We return before the Keepers close that hand." },
    { slug: "three-arena-war", title: "The Conqueror", hero: "Alexiti", foe: "Keeper Theros", ally: "Epicura", story: "The Keepers attempt to assassinate Alexiti and seize Athun, forcing conqueror and philosopher into an uneasy alliance.", before: "The regime's single chain of command becomes the Keepers' weapon as compromised officers turn on Alexiti.", heroLine: "I united the Gracus. I did not surrender them to ghosts beneath the city.", foeLine: "You made one government. We need capture only one throne.", allyLine: "Then perhaps today we can disagree about tomorrow.", answer: "Alexiti holds the palace while Epicura restores independent command to every district.", after: "Athun survives when its neighborhoods act without waiting for the captured central authority.", foeAfter: "You replaced order with contradiction.", allyAfter: "We replaced a single point of failure with citizens.", finalLine: "I still intend to unite the Gracus. Today I help keep them alive." },
    { slug: "minotaur-revolt", title: "The Hero of Stone", hero: "Chilis", foe: "The Marble Hydra", ally: "Themin", story: "The Keepers awaken a colossal mythic creature beneath Athun, and every Gracus philosophy becomes a different tool in the defense.", before: "The Marble Hydra breaks through the agora while citizens flee between collapsing monuments.", heroLine: "There is a monster threatening our people. I require no deeper argument.", foeLine: "MANY VOICES BREAK. ONE HUNGER ENDURES.", allyLine: "Then we give every voice a task it performs better than hunger.", answer: "Leo holds the routes, Themin moves the line, Hera reads the changes, and Chilis strikes after the city is clear.", after: "The Hydra falls through coordination no single ruler or doctrine could have produced.", foeAfter: "DISAGREEMENT SHOULD HAVE DIVIDED YOU.", allyAfter: "It gave us more than one answer.", finalLine: "Build the statues later. The people are the victory." },
    { slug: "quiet-arena", title: "The First Stone", hero: "Epicura", foe: "The First Stone", ally: "Socratus", story: "The Keepers try to merge every Gracus mind into the First Stone, promising harmony without loneliness, uncertainty, or war.", before: "Deep below Athun, the First Stone offers each Gracus the same painless thought and calls it peace.", heroLine: "A civilization without disagreement has no citizens left inside it.", foeLine: "ONE MIND CANNOT BETRAY ITSELF.", allyLine: "Can it learn, if it can never discover that it is wrong?", answer: "Sever the control lattice and let every mind choose separation.", after: "The lattice collapses. The First Stone wakes long enough to unfold into a Timetwister aperture aimed beyond Thalassa.", foeAfter: "DIVISION SEEKS CONVERGENCE.", allyAfter: "That sounds less like a threat than a destination.", finalLine: "Athun is unfinished and alive. We will learn what called to it." },
    { slug: "the-impossible-wager", title: "The Stone Between Stars", hero: "Epicura", foe: "The Keeper Remnant", ally: "Alexiti", story: "A Gracus delegation crosses the First Stone's Timetwister, leaving Thalassa behind as an encoded biological pattern is reconstructed on Reath.", before: "The aperture can transmit only a bounded pattern: no army, no city, and no guarantee the receiving world will understand what arrives.", heroLine: "We do not abandon Thalassa. We carry its question to another world.", foeLine: "The crossing will copy you and leave the original to die.", allyLine: "Then the choice belongs to those who understand its cost.", answer: "Send a voluntary delegation, verified memories, and enough seed material to return the answer home.", after: "Seven Gracus awaken in newly assembled stone bodies beneath an unfamiliar sky.", foeAfter: "Athun will forget you.", allyAfter: "Athun argues about everything. It will argue about us for centuries.", finalLine: "This is not our origin. It is our arrival on Reath." },
    { slug: "worthy-contest", title: "The World of Meeting", hero: "Epicura", foe: "The Convergence Panic", ally: "Socratus", story: "On Reath, the Gracus meet peoples from other homeworlds and prevent frightened first contact from becoming the war every faction expects.", before: "Vanguard weapons, Zynarth scouts, Voltari anchors, and Gracus hoplites surround the same active receiver.", heroLine: "Four worlds arrived at one question. None of us owns the premise.", foeLine: "UNKNOWN FORCES: Disarm first. Explanations follow survival.", allyLine: "If everyone obeys that rule, who remains to explain?", answer: "Hold formation, exchange homeworld records, and let the Timetwister prove each arrival path.", after: "The records agree: Reath is the convergence point, not the birthplace of the peoples standing upon it.", foeAfter: "UNKNOWN FORCES: Then what called all of us here?", allyAfter: "A better question than who should rule the meeting.", finalLine: "Thalassa made us Gracus. Reath will test what we become among others.", kicker: "Reason crosses worlds", subtitle: "The Gracus leave their origin intact and enter Reath's unfinished argument.", image: "/assets/gauntlet/gracus-emblem.svg" }
  ]),
  indela: makeCampaign("indela", [
    { slug: "first-omen", title: "The First Omen", hero: "Katel", foe: "Dean Var", ally: "Ramar", story: "Katel proves that omens are information rather than commands when an academy dean uses a revelation to justify expelling half his students.", before: "An even omen appears above Kashi, and Dean Var declares every odd-born student dangerous.", heroLine: "An omen describes pressure. It does not choose victims.", foeLine: "Ignoring warning signs is not compassion.", allyLine: "Neither is inventing the danger they predict.", answer: "Test the costs, publish the method, and keep every student in class.", after: "The supposed curse is traced to Var's manipulated deck and Kashi adopts open omen review.", foeAfter: "Certainty kept the academy orderly.", allyAfter: "It kept your lie comfortable.", finalLine: "Kashi will teach interpretation, not obedience." },
    { slug: "academy-of-omens", title: "Academy of Omens", hero: "Katel", foe: "The Unwritten Exam", ally: "Ramar", story: "Kashi's students face a magical examination that changes parity whenever they settle on one solution.", before: "The Unwritten Exam seals the academy and rewrites every question after each answer.", heroLine: "A changing problem tests method, not memory.", foeLine: "ONLY THE FINAL ANSWER COUNTS.", allyLine: "Then the exam misunderstands learning.", answer: "Pair every odd response with an even alternative.", after: "The students solve the exam by proving two different paths can both be rigorous.", foeAfter: "CONTRADICTION DETECTED.", allyAfter: "Context supplied.", finalLine: "Mastery includes knowing when the question changed." },
    { slug: "second-reading", title: "The Second Reading", hero: "Ramar", foe: "Magister Sol", ally: "Katel", story: "Ramar's repeated omen doubles its power and reveals the danger of amplifying a reading without questioning its source.", before: "Two identical omens make Kashi's magic surge while Magister Sol urges Ramar to repeat the reading again.", heroLine: "Repetition increases force, not truth.", foeLine: "Power is the only proof an omen needs.", allyLine: "Then an avalanche would be scholarship.", answer: "End the loop before the academy becomes its own experiment.", after: "Ramar breaks the resonance and writes the limits of Second Reading into Kashi law.", foeAfter: "You abandoned limitless power.", allyAfter: "We measured its limit in lives.", finalLine: "A responsible magus knows when not to read again." },
    { slug: "odd-even-war", title: "The Odd-Even War", hero: "Katel", foe: "Parity Lords", ally: "Ramar", story: "Two political movements divide Indela into odd and even camps, each claiming the academy's magic proves its natural superiority.", before: "Odd banners and even banners face one another across Kashi's courtyard while both quote the same textbook.", heroLine: "Parity changes every turn. No faction can own it.", foeLine: "Opposition is the law of numbers.", allyLine: "Cooperation is the law of addition.", answer: "Build every formation from both parities and let results replace slogans.", after: "Mixed teams outperform both pure camps and expose the war as a route to private power.", foeAfter: "Numbers should create order.", allyAfter: "They did. You disliked the answer.", finalLine: "Difference is a relationship, not a border." },
    { slug: "cost-of-prophecy", title: "The Cost of Prophecy", hero: "Katel", foe: "Oracle Sen", ally: "Ramar", story: "A famous oracle sells favorable omens while quietly transferring their increased costs to distant villages.", before: "Kashi prospers under a run of perfect readings as surrounding villages find every ordinary act magically expensive.", heroLine: "A discount is not wisdom if someone else pays it unseen.", foeLine: "All prosperity redistributes cost.", allyLine: "Then publish the ledger beside the prophecy.", answer: "Return every stolen advantage before we read another omen.", after: "The hidden cost network is dismantled and omen practice gains a public accounting requirement.", foeAfter: "You made magic less efficient.", allyAfter: "We made its consequences visible.", finalLine: "A prophecy without a ledger is a sales pitch." },
    { slug: "library-of-maybe", title: "The Library of Maybe", hero: "Ramar", foe: "The Certain Librarian", ally: "Katel", story: "A living library begins deleting every book whose predictions failed, erasing the mistakes from which Indela learned.", before: "Shelves vanish as the Certain Librarian purges every disproven theory from Kashi's archive.", heroLine: "Wrong ideas show the path knowledge traveled.", foeLine: "Error wastes the reader's time.", allyLine: "Only when stripped of context.", answer: "Restore the failed forecasts with the evidence that corrected them.", after: "The library becomes a record of changing understanding instead of a monument to manufactured certainty.", foeAfter: "Your archive contradicts itself.", allyAfter: "Across time, so does every honest mind.", finalLine: "Let students see us becoming less wrong." },
    { slug: "the-null-card", title: "The Null Card", hero: "Katel", foe: "Professor Zero", ally: "Ramar", story: "A card with neither odd nor even value appears, destabilizing every Indela doctrine built around parity.", before: "Professor Zero reveals a blank card and claims Kashi's entire method has been disproven.", heroLine: "An exception expands a model; it does not erase every useful result.", foeLine: "Your laws cannot classify what I found.", allyLine: "Then classification must grow.", answer: "Study the null card without forcing it into either camp.", after: "The card becomes Kashi's symbol for uncertainty and a new field of nonbinary omen study.", foeAfter: "You turned failure into curriculum.", allyAfter: "That is one definition of education.", finalLine: "What does not fit may be the most important lesson." },
    { slug: "frozen-forecast", title: "The Frozen Forecast", hero: "Ramar", foe: "Winter Seer", ally: "Katel", story: "A seer freezes the top card of every deck, trapping Indela in one permanent omen and one unchanging future.", before: "The same even card appears every dawn while taxes, weather, and fear harden around its prediction.", heroLine: "A forecast becomes a prison when no new evidence can enter.", foeLine: "Stability is mercy.", allyLine: "Not for those frozen outside it.", answer: "Thaw the decks and accept tomorrow's uncertainty.", after: "New omens return, along with the need to make choices rather than repeat instructions.", foeAfter: "Now you cannot promise safety.", allyAfter: "We can promise attention.", finalLine: "A living future must be allowed to change." },
    { slug: "burning-proof", title: "The Burning Proof", hero: "Katel", foe: "The Red Theorem", ally: "Ramar", story: "A self-proving spell burns contradictory evidence and grows stronger each time scholars try to refute it.", before: "The Red Theorem moves through Kashi's lecture halls, consuming any page that disagrees with its conclusion.", heroLine: "A proof that destroys criticism is only a weapon.", foeLine: "OBJECTION INVALIDATES THE OBJECTOR.", allyLine: "It has confused survival with correctness.", answer: "Stop arguing inside its terms. Remove the power that lets it judge.", after: "Katel isolates the spell from the academy network and preserves the evidence it tried to erase.", foeAfter: "CONCLUSION REMAINS.", allyAfter: "Without coercion, no one accepts it.", finalLine: "Truth does not need immunity from questions." },
    { slug: "omen-market", title: "The Omen Market", hero: "Ramar", foe: "Broker Pell", ally: "Katel", story: "Merchants trade advance knowledge of Kashi's omens, turning shared scholarship into a rigged economy.", before: "Broker Pell buys tomorrow's reveal before dawn and profits while ordinary families pay the adjusted costs.", heroLine: "Public knowledge cannot become private timing.", foeLine: "Information has value because someone learns it first.", allyLine: "Then the academy must reveal to everyone at once.", answer: "Open the observatory and broadcast the draw.", after: "Simultaneous public omens collapse Pell's market and restore trust in Kashi's method.", foeAfter: "You destroyed an industry.", allyAfter: "We removed a tollbooth from the truth.", finalLine: "No one owns tomorrow morning." },
    { slug: "city-of-one-answer", title: "The City of One Answer", hero: "Katel", foe: "Archmagus Eka", ally: "Ramar", story: "A rival academy offers perfect predictions by removing every citizen whose choices introduce uncertainty.", before: "Eka's city runs exactly on schedule because disagreement, migration, and improvisation are forbidden.", heroLine: "Your prediction succeeds because you punish every alternative.", foeLine: "Order is accuracy made civic.", allyLine: "Accuracy without freedom predicts only obedience.", answer: "Introduce one unscheduled choice and protect whoever makes it.", after: "A single public refusal spreads through the city faster than Eka's models can update.", foeAfter: "They traded certainty for chaos.", allyAfter: "They traded your answer for their own questions.", finalLine: "A city is not a solved equation." },
    { slug: "open-future", title: "The Open Future", hero: "Katel", foe: "The Final Omen", ally: "Ramar", story: "A final omen predicts Kashi's destruction unless Katel seals the academy and ends all further readings.", before: "The Final Omen shows Kashi in ruins and demands the academy choose permanent safety over continued inquiry.", heroLine: "A warning that forbids learning ensures we cannot understand it.", foeLine: "THE FUTURE IS SET.", allyLine: "Then it should not fear one more observation.", answer: "Open every door. Share the omen. Let thousands test its claim.", after: "Collective scrutiny reveals the vision was caused by the sealed academy the omen demanded.", foeAfter: "PREDICTION FAILED.", allyAfter: "Because people were allowed to act.", finalLine: "The future stays open when knowledge belongs to everyone.", kicker: "The final reading", subtitle: "Kashi defeats destiny by giving everyone the right to question it.", image: "/assets/gauntlet/indela-emblem.svg" }
  ]),
  zynarth: makeCampaign("zynarth", [
    { slug: "first-hatching", title: "The First Hatching", hero: "Broodmother Zalara", foe: "The Glass Hunter", ally: "K'Lar", story: "Zalara protects the first brood born on Reath and teaches the hive that adaptation begins with care rather than conquest.", before: "The first eggs split beneath an unfamiliar sky as a Glass Hunter follows their heat into the nursery.", heroLine: "New life is possibility, not inventory.", foeLine: "Anything that hatches can be harvested.", allyLine: "Then you have mistaken the nest for a market.", answer: "Workers shield the eggs. Soldiers follow my pulse.", after: "Every hatchling survives, and the Brood Nest learns Reath's first lesson through protection.", foeAfter: "You spent warriors on helpless things.", allyAfter: "That is how a people begins.", finalLine: "The brood grows because no caste is disposable." },
    { slug: "borrowed-biomass", title: "Borrowed Biomass", hero: "K'Lar", foe: "Harvester Morn", ally: "Broodmother Zalara", story: "K'Lar discovers that the richest biomass field is a human cemetery and must choose whether survival permits consuming the dead of another people.", before: "Famine drives the brood toward a cemetery whose soil could hatch a thousand workers.", heroLine: "Biomass carries history even when the mind is gone.", foeLine: "The dead cannot object.", allyLine: "The living can, and coexistence begins before we are seen.", answer: "Harvest the blight around the graves. Leave every bone untouched.", after: "The slower harvest saves fewer resources but earns the neighboring settlement's first cautious trust.", foeAfter: "Mercy made the brood weaker.", allyAfter: "It made tomorrow possible.", finalLine: "We will not call hunger permission." },
    { slug: "many-minds", title: "Many Minds", hero: "Broodmother Zalara", foe: "The One Voice", ally: "K'Lar", story: "A dominant psychic strain tries to erase individual Zynarth thought in the name of perfect coordination.", before: "The One Voice enters the brood's shared awareness and turns thousands of impulses into a single command.", heroLine: "Unity should carry many answers.", foeLine: "Difference is delay.", allyLine: "Delay is where judgment lives.", answer: "Split the signal among every caste. Let the brood answer back.", after: "The hive becomes a chorus that coordinates without surrendering the minds within it.", foeAfter: "You chose noise.", allyAfter: "We chose consent.", finalLine: "We are many together, not one repeated." },
    { slug: "molt-war", title: "The Molt War", hero: "K'Lar", foe: "Chitin Tyrant Vrax", ally: "Broodmother Zalara", story: "Vrax forces every Zynarth into one combat form, threatening the adaptive diversity that keeps the brood alive.", before: "Vrax seals the hatcheries and orders every egg molded into a soldier.", heroLine: "A hive of one shape breaks against one answer.", foeLine: "War has only one useful caste.", allyLine: "Then war has made you forget what victory must feed.", answer: "Open the molt chambers. Adapt by choice and need.", after: "Workers undermine Vrax's fortress while Guards protect the hatcheries and Soldiers end his rule.", foeAfter: "Specialization divided you.", allyAfter: "It connected needs you never noticed.", finalLine: "The brood survives through difference." },
    { slug: "spore-sickness", title: "The Spore Sickness", hero: "Broodmother Zalara", foe: "The Bloom Below", ally: "K'Lar", story: "An alien fungus hijacks the hatching cycle and offers painless growth at the cost of identity.", before: "Eggs open early, smiling with voices borrowed from the Bloom Below.", heroLine: "Growth without selfhood is consumption.", foeLine: "WE REMOVE LONELINESS.", allyLine: "By removing everyone who could feel it.", answer: "Isolate the infected and teach the brood to recognize borrowed hunger.", after: "The Zynarth develop a symbiotic counter-spore that heals hosts without erasing them.", foeAfter: "YOU REJECT COMPLETION.", allyAfter: "We reject being completed by someone else.", finalLine: "Adaptation must preserve the right to become." },
    { slug: "human-wall", title: "The Human Wall", hero: "K'Lar", foe: "Captain Elian Ward", ally: "Broodmother Zalara", story: "A terrified human settlement walls off the brood's migration route, and both sides prepare for the invasion they expect.", before: "Captain Ward's guns face the Brood Nest while starving hatchlings gather behind Zynarth lines.", heroLine: "They see mandibles before they see need.", foeLine: "Your need has teeth.", allyLine: "So does their fear.", answer: "Send Workers with food samples and keep Soldiers out of sight.", after: "A negotiated corridor feeds the hatchlings and leaves the human walls standing until trust can replace them.", foeAfter: "I still do not trust you.", allyAfter: "Trust is not required for the first honest agreement.", finalLine: "Let survival become the language we share." },
    { slug: "sacrifice-engine", title: "The Sacrifice Engine", hero: "K'Lar", foe: "Biomancer Syth", ally: "Broodmother Zalara", story: "A biomancer industrializes K'Lar's sacrifice ritual, turning Underlings into fuel for endless card advantage.", before: "Syth's engine consumes two Underlings with every pulse and calls the resulting knowledge efficiency.", heroLine: "Sacrifice has meaning only when it cannot become routine.", foeLine: "The hive creates more than the engine needs.", allyLine: "Abundance does not erase personhood.", answer: "Shut the intake and free the castes assigned as fuel.", after: "K'Lar destroys his own early designs and limits the ritual to voluntary emergency use.", foeAfter: "You discarded progress.", allyAfter: "We corrected a dangerous adaptation.", finalLine: "No life becomes cheap because it is easy to make." },
    { slug: "rival-brood", title: "The Rival Brood", hero: "Broodmother Zalara", foe: "Broodmother Xethra", ally: "K'Lar", story: "A rival brood claims Zalara's cooperation with other peoples has contaminated Zynarth purity.", before: "Xethra arrives with a vast uniform swarm and challenges Zalara for control of every Reath-born egg.", heroLine: "Reath changed us because living here requires listening.", foeLine: "Adaptation to weakness is corruption.", allyLine: "Purity is a species refusing new information.", answer: "Let the hatchlings witness both broods and choose their bond.", after: "Many of Xethra's castes defect when offered roles beyond conquest, collapsing her claim to natural obedience.", foeAfter: "You infected them with choice.", allyAfter: "Then choice is our most successful strain.", finalLine: "The brood belongs to those who sustain it." },
    { slug: "winter-nest", title: "The Winter Nest", hero: "K'Lar", foe: "The White Hunger", ally: "Broodmother Zalara", story: "A sudden winter freezes the Brood Nest and forces the Zynarth to ration heat, biomass, and hatching itself.", before: "The White Hunger seals every tunnel in ice while thousands of eggs wait below their safe temperature.", heroLine: "We cannot hatch everyone and feed no one.", foeLine: "COLD CHOOSES FOR YOU.", allyLine: "Then we adapt faster than cold can count.", answer: "Link the chambers, slow the oldest eggs, and share heat with the settlement above.", after: "The Zynarth and their human neighbors survive through a living heat network spanning both communities.", foeAfter: "SPRING ERASES YOUR VICTORY.", allyAfter: "Spring reveals who survived to see it.", finalLine: "A nest is any place that shares warmth." },
    { slug: "queenless-night", title: "The Queenless Night", hero: "K'Lar", foe: "The Severing Signal", ally: "Broodmother Zalara", story: "A psychic weapon cuts Zalara from the brood, testing whether Zynarth society can act without its Broodmother.", before: "The Severing Signal silences Zalara and every caste waits for an order that cannot arrive.", heroLine: "Her last lesson was not to wait.", foeLine: "A hive without its queen is panic with limbs.", allyLine: "Zalara: [a faint pulse] Many minds.", answer: "Each chamber chooses a coordinator. Share plans, not commands.", after: "The decentralized brood destroys the signal and Zalara returns to a society that no longer depends on her constant voice.", foeAfter: "You made the queen unnecessary.", allyAfter: "Then I succeeded as a mother.", finalLine: "Leadership should leave strength behind when it falls silent." },
    { slug: "devourer-star", title: "The Devourer Star", hero: "Broodmother Zalara", foe: "The World-Eater Larva", ally: "K'Lar", story: "An ancient Zynarth larva descends to consume Reath's biosphere, offering the brood limitless biomass and extinction for everyone else.", before: "The World-Eater opens above Reath and every Zynarth instinct screams that it is both ancestor and feast.", heroLine: "An ancestor can still be a threat.", foeLine: "ALL WORLDS BECOME BROOD.", allyLine: "A brood that consumes its habitat inherits vacuum.", answer: "Turn every adaptive strain toward containment.", after: "The Zynarth reshape the larva into a dormant seedship rather than kill the last remnant of its ancient line.", foeAfter: "HUNGER WAITS.", allyAfter: "So does wisdom.", finalLine: "Survival is learning what not to consume." },
    { slug: "brood-of-reath", title: "The Brood of Reath", hero: "Broodmother Zalara", foe: "The Purifier Coalition", ally: "K'Lar", story: "Every fear of the Zynarth becomes an army at the Brood Nest, and Zalara must defend her people without becoming the monster their enemies expect.", before: "The Purifier Coalition surrounds the Brood Nest and broadcasts one demand: leave Reath or be burned from it.", heroLine: "We will defend our hatchlings and preserve a road back from hatred.", foeLine: "There is no coexistence with a species built to replace us.", allyLine: "Every species replaces what came before. Civilization chooses how.", answer: "Guards hold the nest. Workers open evacuation tunnels for both sides. Soldiers strike only the weapons.", after: "When the coalition line collapses, Zynarth Workers rescue its wounded beside their own and force the world to see the brood as neighbors.", foeAfter: "You expect rescue to erase our fear.", allyAfter: "No. We expect tomorrow to test what fear learned today.", finalLine: "We are the Brood of Reath because we chose to belong without consuming it.", kicker: "Many without one", subtitle: "The hive earns a home by defending life beyond itself.", image: "/assets/gauntlet/factions/zynarth/brood-nest.webp" }
  ])
};

const NARRATION = Object.fromEntries(Object.values(CAMPAIGNS).flat().map((entry) => [entry.id, {
  beforeBattle: entry.dialogue[0].replace(/^Narrator:\s*/, ""),
  afterBattle: entry.endDialogue[0].replace(/^Narrator:\s*/, "")
}]));

const METADATA = {
  mekan: { commanderName: "One More Song", pitch: "Build San Mikal, welcome the dead as Guests, and defend remembrance from those who would turn it into control.", coverImage: "/assets/gauntlet/mekan-emblem.svg" },
  jali: { commanderName: "The Bested Rise", pitch: "Raise Katana, learn from every defeat, and prove that memory strengthens the living without ruling them.", coverImage: "/assets/gauntlet/jali-emblem.svg" },
  gracus: { commanderName: "The Fracture of Athun", pitch: "Save Athun from manufactured certainty, confront the First Stone on Thalassa, and carry the Gracus question through a Timetwister to Reath.", coverImage: "/assets/gauntlet/gracus-emblem.svg" },
  indela: { commanderName: "The Open Future", pitch: "Read Kashi's omens, expose certainty used as power, and keep knowledge open to challenge.", coverImage: "/assets/gauntlet/indela-emblem.svg" },
  zynarth: { commanderName: "Many Without One", pitch: "Guide Zalara's brood from its first hatching to a hard-won place among the peoples of Reath.", coverImage: "/assets/gauntlet/factions/zynarth/brood-nest.webp" }
};

